  /* 1인분 프리셋 — 사진보다 이게 정확합니다 */
  var PORTIONS = [
    { label: '반', mult: 0.5 },
    { label: '1인분', mult: 1 },
    { label: '1.5', mult: 1.5 },
    { label: '2인분', mult: 2 }
  ];

  var CONF_LABEL = {
    high: { text: '편차 작음', note: '조리법이 단순해 값이 비교적 일정합니다' },
    mid:  { text: '식당마다 다름', note: '±20% 정도는 흔합니다' },
    low:  { text: '편차 큼', note: '양념·기름 때문에 ±40%도 납니다. 자주 먹으면 직접 보정하세요' }
  };

  function search(q, limit) {
    q = String(q || '').trim().toLowerCase();
    if (!q) return [];
    var out = [];
    for (var i = 0; i < FOODS.length; i++) {
      var x = FOODS[i];
      var hay = (x.name + ' ' + x.alias + ' ' + x.cat).toLowerCase();
      var idx = hay.indexOf(q);
      if (idx >= 0) out.push({ food: x, score: (x.name.toLowerCase().indexOf(q) === 0 ? 0 : 1) + idx * 0.001 });
    }
    out.sort(function (a, b) { return a.score - b.score; });
    return out.slice(0, limit || 30).map(function (o) { return o.food; });
  }

  function byCat(cat) {
    return FOODS.filter(function (x) { return x.cat === cat; });
  }
  function byName(name) {
    for (var i = 0; i < FOODS.length; i++) if (FOODS[i].name === name) return FOODS[i];
    return null;
  }
  /** 배수를 적용한 실제 섭취값 */
  function scaled(food, mult) {
    mult = mult || 1;
    return {
      name: food.name, unit: food.unit, mult: mult,
      g: Math.round(food.g * mult),
      kcal: Math.round(food.kcal * mult),
      p: Math.round(food.p * mult * 10) / 10,
      c: Math.round(food.c * mult * 10) / 10,
      f: Math.round(food.f * mult * 10) / 10,
      conf: food.conf
    };
  }

  global.MB_FOOD = {
    FOODS: FOODS, CATS: CATS, PORTIONS: PORTIONS, CONF_LABEL: CONF_LABEL,
    search: search, byCat: byCat, byName: byName, scaled: scaled
  };
